-- High school clearance rules and youth-only USA Lacrosse Bronze.
-- Sources: Seneca Valley athletic office email (Oct 13, 2026), the district Employee Clearance Application directions,
-- and WPYLA League Rules section 6 (Coaches Rosters).
--
-- This file is a SNAPSHOT of the live requirement rows (they were refined in the database after the first draft of this
-- file). It is idempotent: running it again changes nothing. The first draft appended text on every run, so do not
-- restore it from history.
insert into public.requirements (id, sort_order, definition) values
  ('pa-child-abuse', 1, $json${"help": "Apply online through the PA Department of Human Services. It is free for volunteers. Results usually arrive by email within 14 days. Upload the PDF certificate. High school coaches: apply as a Seneca Valley employee (purpose: Employee Governed by Public School Code) and follow the Seneca Valley athletic office's instructions. Last season's staff already have clearances on file for five years of continuous service.", "name": "PA Child Abuse History Clearance", "type": "File", "active": true, "helpUrl": "https://www.compass.state.pa.us/cwis/public/home", "required": true, "validity": {"kind": "years", "years": 5}, "appliesToPay": ["Paid", "Volunteer"], "helpLinkLabel": "PA Child Welfare Portal", "appliesToRoles": ["Head Coach", "Coordinator", "Assistant Coach", "Volunteer Assistant"], "tracksObtainedAs": true}$json$::jsonb),
  ('pa-state-police', 2, $json${"help": "Request a check online through PATCH. Results are often instant. Save the certificate as a PDF and upload it here. High school coaches: request it for employment, as a Seneca Valley employee, and follow the Seneca Valley athletic office's instructions. Last season's staff already have clearances on file for five years of continuous service.", "name": "PA State Police Criminal Record Check", "type": "File", "active": true, "helpUrl": "https://epatch.pa.gov/", "required": true, "validity": {"kind": "years", "years": 5}, "appliesToPay": ["Paid", "Volunteer"], "helpLinkLabel": "PA State Police PATCH", "appliesToRoles": ["Head Coach", "Coordinator", "Assistant Coach", "Volunteer Assistant"], "tracksObtainedAs": true}$json$::jsonb),
  ('fbi-fingerprint', 3, $json${"help": "Register with IdentoGO and get fingerprinted at a local site. Youth volunteers who have lived in PA for the past 10 years may sign a Volunteer Disclosure Statement instead. Paid coaches and all high school coaches must get fingerprinted. High school coaches: follow the Seneca Valley athletic office instructions for registering.", "name": "FBI Fingerprint Check", "type": "File", "active": true, "helpUrl": "https://uenroll.identogo.com/", "required": true, "validity": {"kind": "years", "years": 5}, "appliesToPay": ["Paid", "Volunteer"], "helpLinkLabel": "IdentoGO fingerprinting", "appliesToRoles": ["Head Coach", "Coordinator", "Assistant Coach", "Volunteer Assistant"], "tracksObtainedAs": true, "allowsVolunteerAffidavit": true}$json$::jsonb),
  ('usal-bronze', 5, $json${"why": "WPYLA requires every youth coach to complete USA Lacrosse training, and each team must have at least one Bronze-certified coach to be eligible to play. Bronze is the USA Lacrosse baseline training, including the background screen, abuse prevention, concussion and cardiac care.", "help": "Log in to your USA Lacrosse account\nAdd Coach as your involvement on profile\n\n to complete the background screen and the free Bronze level online course. \n\nUpload the certificate and enter the completion date.", "name": "USA Lacrosse Background Screen & Bronze Certification", "type": "File", "level": "youth", "active": true, "source": "WPYLA League Rules, section 6 (Coaches Rosters). Not required for high school coaches.", "helpUrl": "https://www.usalacrosse.com/coaches", "required": true, "validity": {"kind": "years", "years": 2}, "appliesToPay": ["Paid", "Volunteer"], "helpLinkLabel": "USA Lacrosse coaching", "appliesToRoles": ["Head Coach", "Coordinator", "Assistant Coach", "Volunteer Assistant"], "dateOnlyAllowed": true}$json$::jsonb),
  ('concussion', 6, $json${"help": "Take one NFHS Learn concussion course: 'Concussion in Sports' or 'Sport Safety - Play Safely!' (free). It must be retaken every school year. Upload the completion certificate. A printed certificate is not required.", "name": "Annual Concussion Training", "type": "Training", "active": true, "helpUrl": "https://www.nfhslearn.com/", "required": true, "validity": {"kind": "school-year"}, "appliesToPay": ["Paid", "Volunteer"], "helpLinkLabel": "NFHS Learn (search Concussion in Sports)", "appliesToRoles": ["Head Coach", "Coordinator", "Assistant Coach", "Volunteer Assistant"]}$json$::jsonb),
  ('sudden-cardiac', 7, $json${"help": "Take one NFHS Learn cardiac course: 'Sudden Cardiac Arrest' or 'Sport Safety - Play Safely!' (free). It must be retaken every school year. Upload the completion certificate. A printed certificate is not required.", "name": "Annual Sudden Cardiac Arrest Training", "type": "Training", "active": true, "helpUrl": "https://www.nfhslearn.com/courses/sudden-cardiac-arrest", "required": true, "validity": {"kind": "school-year"}, "appliesToPay": ["Paid", "Volunteer"], "helpLinkLabel": "NFHS Learn courses", "appliesToRoles": ["Head Coach", "Coordinator", "Assistant Coach", "Volunteer Assistant"]}$json$::jsonb),
  ('piaa-rules-meeting', 11, $json${"why": "PIAA requires each high school head coach to attend a rules interpretation meeting every year so games are coached to the current rules.", "help": "Find a District 7 meeting on the PIAA website (Rules Meetings), attend, and upload proof of attendance or enter the date you attended.", "name": "PIAA Rules Interpretation Meeting", "type": "File", "level": "high-school", "active": true, "source": "PIAA, through the Seneca Valley athletic office. Seneca Valley is in District 7.", "helpUrl": "https://www.piaa.org/", "required": true, "validity": {"kind": "school-year"}, "sourceUrl": "https://www.piaa.org/", "appliesToPay": ["Paid", "Volunteer"], "helpLinkLabel": "PIAA rules meetings", "appliesToRoles": ["Head Coach"], "dateOnlyAllowed": true}$json$::jsonb)
on conflict (id) do update set definition = excluded.definition;
